{"command":"cat <<'EOF' > htop_clone.py
import os
import time
import curses

def get_uptime():
    with open('/proc/uptime', 'r') as f:
        return float(f.readline().split()[0])

def get_load_avg():
    with open('/proc/loadavg', 'r') as f:
        return f.readline().split()[:3]

def get_mem_info():
    mem = {}
    with open('/proc/meminfo', 'r') as f:
        for line in f:
            parts = line.split()
            if len(parts) >= 2:
                mem[parts[0].rstrip(':')] = int(parts[1])
    return mem

def get_cpu_stats():
    with open('/proc/stat', 'r') as f:
        for line in f:
            if line.startswith('cpu '):
                parts = line.split()
                # user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice
                return [int(x) for x in parts[1:]]
    return []

def main(stdscr):
    curses.curs_set(0)
    stdscr.nodelay(True)
    stdscr.timeout(1000)

    while True:
        stdscr.clear()
        uptime = get_uptime()
        load_avg = get_load_avg()
        mem = get_mem_info()
        cpu = get_cpu_stats()

        stdscr.addstr(0, 0, f"Uptime: {uptime}, Load: {', '.join(load_avg)}")
        stdscr.addstr(1, 0, f"Mem: {mem.get('MemTotal', 0)} / {mem.get('MemFree', 0)}")

        stdscr.refresh()

        try:
            key = stdscr.getch()
            if key == ord('q'):
                break
        except:
            pass

        time.sleep(1)

if __name__ == "__main__":
    curses.wrapper(main)
EOF
# Test it briefly
# python3 htop_clone.py
"}

